_ITEMS = [
    ("phishing", "Phishing Attacks", "ఫిషింగ్ దాడులు", "A fake email, message, or page tries to make you reveal information or open a harmful link.", "నకిలీ ఈమెయిల్, సందేశం లేదా వెబ్‌పేజీ ద్వారా మీ సమాచారాన్ని చెప్పించడానికి లేదా అనుమానాస్పద లింక్ తెరవించడానికి ప్రయత్నిస్తారు.", "A sender pretends to be a trusted organization and asks you to sign in through a link.", "నమ్మకమైన సంస్థగా నటించి, లింక్ ద్వారా ఖాతాలోకి ప్రవేశించమని అడుగుతారు.", "Unexpected links; pressure to act; spelling or address that differs from the real organization.", "అనుకోని లింకులు; వెంటనే చేయాలనే ఒత్తిడి; నిజమైన సంస్థ చిరునామాతో తేడా.", "A delivery message says a parcel is held and asks you to enter card details on a linked page.", "పార్సెల్ ఆగిపోయిందని చెప్పి, లింక్‌లో కార్డు వివరాలు నమోదు చేయమని సందేశం రావడం.", "Open the official app or type the known website address yourself; do not use the message link.", "అధికారిక యాప్‌ను తెరవండి లేదా మీకు తెలిసిన వెబ్ చిరునామాను స్వయంగా టైప్ చేయండి; సందేశంలోని లింక్‌ను వాడవద్దు.", "If you entered a password, change it using the official site and contact the organization. If money was lost, call 1930 promptly.", "పాస్‌వర్డ్ ఇచ్చినట్లయితే అధికారిక సైట్‌లో దాన్ని మార్చి సంస్థను సంప్రదించండి. డబ్బు పోయితే వెంటనే 1930కు కాల్ చేయండి."),
    ("otp-fraud", "OTP Fraud", "ఓటీపీ మోసం", "Someone tricks you into sharing a one-time code that can approve a sign-in or transaction.", "లాగిన్ లేదా లావాదేవీకి ఉపయోగించే ఒకసారి కోడ్‌ను చెప్పించేలా మోసగాళ్లు ప్రయత్నిస్తారు.", "A caller claims to be support and asks you to read out a code you just received.", "సహాయక సిబ్బందిగా నటించి, ఇప్పుడే వచ్చిన కోడ్ చెప్పమని అడగడం.", "Requests to share an OTP, PIN, password, or screen; a code arrives for an action you did not start.", "ఓటీపీ, పిన్, పాస్‌వర్డ్ లేదా స్క్రీన్ పంచమని అడగడం; మీరు ప్రారంభించని చర్యకు కోడ్ రావడం.", "A caller says your account will be blocked unless you tell them the SMS code.", "ఎస్‌ఎంఎస్ కోడ్ చెప్పకపోతే ఖాతా నిలిపివేస్తామని కాలర్ చెప్పడం.", "Never read a verification code to another person. Stop and contact the service through its official app or number.", "ధృవీకరణ కోడ్‌ను ఎవరికీ చెప్పవద్దు. మాట్లాడటం ఆపి అధికారిక యాప్ లేదా నంబర్ ద్వారా సేవను సంప్రదించండి.", "Contact your bank or service provider immediately, secure the account, and call 1930 if a financial transaction occurred.", "బ్యాంక్ లేదా సేవా సంస్థను వెంటనే సంప్రదించి ఖాతాను భద్రపరచండి; డబ్బు లావాదేవీ జరిగితే 1930కు కాల్ చేయండి."),
    ("upi-fraud", "UPI Payment Fraud", "యూపీఐ చెల్లింపు మోసం", "A fraudster misleads you into approving a payment or sharing payment credentials.", "చెల్లింపును ఆమోదించేలా లేదా చెల్లింపు వివరాలు పంచుకునేలా మోసగాళ్లు తప్పుదారి పట్టిస్తారు.", "A fake buyer sends a collect request or asks you to scan a QR code to receive money.", "నకిలీ కొనుగోలుదారు డబ్బు పొందడానికి కలెక్ట్ అభ్యర్థన అంగీకరించమని లేదా QR కోడ్ స్కాన్ చేయమని అడగడం.", "A request asks for your UPI PIN to receive money; payee name or amount differs from what you expect.", "డబ్బు పొందడానికి UPI పిన్ అడగడం; చెల్లింపుదారు పేరు లేదా మొత్తం ఊహించిన దానితో సరిపోకపోవడం.", "A seller says a small PIN entry is needed to release a refund.", "రిఫండ్ పొందడానికి పిన్ నమోదు చేయాలని విక్రేత చెప్పడం.", "Entering a UPI PIN generally authorizes a payment, not receipt of money. Read the app screen before approving.", "UPI పిన్ నమోదు సాధారణంగా చెల్లింపును ఆమోదిస్తుంది, డబ్బు స్వీకరణను కాదు. ఆమోదించే ముందు యాప్ స్క్రీన్ చదవండి.", "Contact your bank and payment app immediately. Call 1930 promptly for financial cyber fraud and keep transaction references.", "బ్యాంక్ మరియు చెల్లింపు యాప్‌ను వెంటనే సంప్రదించండి. ఆర్థిక సైబర్ మోసం జరిగితే 1930కు వెంటనే కాల్ చేసి లావాదేవీ వివరాలు ఉంచండి."),
    ("fake-bank-call", "Fake Bank Calls", "నకిలీ బ్యాంక్ కాల్స్", "A caller pretends to represent a bank and uses fear or urgency to obtain money or secret details.", "బ్యాంక్ ప్రతినిధిగా నటించి భయం లేదా తొందరపాటు కలిగించి డబ్బు లేదా రహస్య వివరాలు అడుగుతారు.", "The caller asks for a PIN, OTP, CVV, remote access, or a transfer to a so-called safe account.", "పిన్, ఓటీపీ, CVV, రిమోట్ యాక్సెస్ లేదా సురక్షిత ఖాతా పేరుతో డబ్బు బదిలీ అడగడం.", "Threats of immediate account closure; requests for secret codes; instructions to install an app or transfer funds.", "ఖాతా వెంటనే మూసేస్తామని బెదిరించడం; రహస్య కోడ్ అడగడం; యాప్ ఇన్‌స్టాల్ లేదా డబ్బు బదిలీ చేయమని చెప్పడం.", "A caller says a suspicious transaction can only be stopped if you share an OTP.", "ఓటీపీ చెబితేనే అనుమానాస్పద లావాదేవీ ఆపగలమని కాలర్ చెప్పడం.", "End the call and call the number printed on your bank card or shown in its official app.", "కాల్‌ను ముగించి, బ్యాంక్ కార్డుపై ఉన్న లేదా అధికారిక యాప్‌లో చూపిన నంబర్‌కు మీరు స్వయంగా కాల్ చేయండి.", "Call your bank using its official number to block or secure access. If money was lost, call 1930 promptly.", "యాక్సెస్ నిలిపివేయడానికి అధికారిక నంబర్ ద్వారా బ్యాంకును సంప్రదించండి. డబ్బు పోయితే వెంటనే 1930కు కాల్ చేయండి."),
    ("fake-job", "Fake Job Offers", "నకిలీ ఉద్యోగ ఆఫర్లు", "A false recruiter uses a job offer to collect fees, identity documents, or account access.", "నకిలీ రిక్రూటర్ ఉద్యోగం పేరుతో ఫీజు, గుర్తింపు పత్రాలు లేదా ఖాతా యాక్సెస్ సేకరిస్తాడు.", "The recruiter asks for payment before an interview or uses an unofficial email and rushed offer.", "ఇంటర్వ్యూకు ముందే డబ్బు అడగడం లేదా అనధికారిక ఈమెయిల్‌తో తొందరపాటు ఆఫర్ ఇవ్వడం.", "Upfront fees; guaranteed income; no verifiable employer contact; requests for OTP or bank login.", "ముందస్తు ఫీజులు; హామీ ఆదాయం; ధృవీకరించలేని సంస్థ సంప్రదింపు; ఓటీపీ లేదా బ్యాంక్ లాగిన్ అడగడం.", "A recruiter asks for a registration fee through a personal payment account to reserve a job.", "ఉద్యోగం ఖరారు చేయడానికి వ్యక్తిగత చెల్లింపు ఖాతాకు రిజిస్ట్రేషన్ ఫీజు పంపమని రిక్రూటర్ అడగడం.", "Verify the vacancy on the employer's official careers page and contact the employer independently.", "సంస్థ అధికారిక కెరీర్స్ పేజీలో ఉద్యోగాన్ని ధృవీకరించి, సంస్థను స్వతంత్రంగా సంప్రదించండి.", "Stop payments, preserve the offer and payment records, contact your bank, and report financial loss through 1930.", "చెల్లింపులు ఆపి ఆఫర్ మరియు చెల్లింపు రికార్డులు భద్రపరచండి, బ్యాంకును సంప్రదించండి, ఆర్థిక నష్టం అయితే 1930 ద్వారా నివేదించండి."),
    ("lottery-prize", "Lottery and Prize Scams", "లాటరీ మరియు బహుమతి మోసాలు", "A message falsely says you won a prize to persuade you to pay a fee or disclose information.", "బహుమతి గెలిచారని తప్పుడు సందేశం పంపి ఫీజు చెల్లించమని లేదా సమాచారం ఇవ్వమని ఒప్పిస్తారు.", "An unsolicited message claims a prize but requires tax, delivery, or processing payment first.", "అనుకోని బహుమతి సందేశం ముందుగా పన్ను, డెలివరీ లేదా ప్రాసెసింగ్ ఫీజు అడగడం.", "You did not enter; a deadline is imposed; payment is requested to release the prize.", "మీరు పోటీలో పాల్గొనకపోయినా గెలిచారని చెప్పడం; గడువు పెట్టడం; బహుమతి విడుదలకు డబ్బు అడగడం.", "A message says a large prize is waiting if you pay a small refundable charge.", "చిన్న మొత్తాన్ని తిరిగి ఇచ్చే ఫీజుగా చెల్లిస్తే పెద్ద బహుమతి ఇస్తామని సందేశం రావడం.", "Do not pay to claim an unexpected prize. Verify any promotion on the organization's official website.", "అనుకోని బహుమతి కోసం డబ్బు చెల్లించవద్దు. సంస్థ అధికారిక వెబ్‌సైట్‌లో ప్రమోషన్‌ను ధృవీకరించండి.", "Save the message and payment details. Contact your bank and call 1930 promptly if money was sent.", "సందేశం, చెల్లింపు వివరాలు భద్రపరచండి. డబ్బు పంపితే బ్యాంకును సంప్రదించి 1930కు వెంటనే కాల్ చేయండి."),
    ("fake-loan", "Fake Loan Applications", "నకిలీ రుణ దరఖాస్తులు", "A false lender uses a loan promise to collect advance fees, identity data, or access to a device.", "రుణం ఇస్తామని చెప్పి ముందస్తు ఫీజు, గుర్తింపు సమాచారం లేదా పరికర యాక్సెస్ సేకరిస్తారు.", "An app or agent promises instant approval but demands repeated fees or broad phone permissions.", "తక్షణ రుణం ఇస్తామని చెప్పి మళ్లీ మళ్లీ ఫీజులు లేదా విస్తృత ఫోన్ అనుమతులు అడగడం.", "Unclear lender identity; advance release fee; pressure to share contacts, OTP, or PIN.", "రుణదాత వివరాలు స్పష్టంగా లేకపోవడం; విడుదల ఫీజు; కాంటాక్టులు, ఓటీపీ లేదా పిన్ అడగడం.", "A supposed lender asks for a processing fee to a personal account before showing loan terms.", "రుణ నిబంధనలు చూపకముందే వ్యక్తిగత ఖాతాకు ప్రాసెసింగ్ ఫీజు పంపమని రుణదాత అడగడం.", "Check the lender's identity and terms independently. Review app permissions and do not share codes.", "రుణదాత గుర్తింపు, నిబంధనలు స్వతంత్రంగా పరిశీలించండి. యాప్ అనుమతులు చూడండి; కోడ్‌లు పంచుకోవద్దు.", "Revoke unnecessary permissions, contact your bank if payment details were exposed, and report financial loss through 1930.", "అవసరం లేని అనుమతులు తొలగించండి; చెల్లింపు వివరాలు బయటపడ్డట్లయితే బ్యాంకును సంప్రదించి, ఆర్థిక నష్టం 1930కు నివేదించండి."),
    ("kyc-scam", "KYC Update Scams", "కేవైసీ నవీకరణ మోసాలు", "A scammer claims your account or SIM will stop unless you urgently update KYC through a link or call.", "లింక్ లేదా కాల్ ద్వారా వెంటనే KYC చేయకపోతే ఖాతా లేదా సిమ్ ఆగిపోతుందని మోసగాళ్లు చెబుతారు.", "A text threatens suspension and links to a lookalike form or app.", "సేవ నిలిపివేస్తామని బెదిరిస్తూ పోలిక ఉన్న ఫారం లేదా యాప్ లింక్ పంపడం.", "Urgent suspension warning; shortened link; request for OTP, PIN, or remote access.", "సేవ నిలిపివేతపై తొందరపాటు హెచ్చరిక; చిన్న లింక్; ఓటీపీ, పిన్ లేదా రిమోట్ యాక్సెస్ అడగడం.", "A message says a bank account will be frozen today unless identity details are entered at a link.", "లింక్‌లో వివరాలు ఇవ్వకపోతే ఈరోజే బ్యాంక్ ఖాతా నిలిపివేస్తామని సందేశం రావడం.", "Check KYC status only in the official app or branch; do not use a message link.", "అధికారిక యాప్ లేదా శాఖలోనే KYC స్థితి పరిశీలించండి; సందేశ లింక్ వాడవద్దు.", "Contact the bank or telecom provider through official channels, secure accounts, and call 1930 if money was lost.", "అధికారిక మార్గంలో బ్యాంక్ లేదా టెలికాం సంస్థను సంప్రదించి ఖాతాలను భద్రపరచండి; డబ్బు పోతే 1930కు కాల్ చేయండి."),
    ("social-account", "Social Media Account Hacking", "సోషల్ మీడియా ఖాతా హ్యాకింగ్", "Someone gains access to an account or impersonates its owner to contact others.", "ఎవరైనా ఖాతాలోకి ప్రవేశించి లేదా యజమానిలా నటించి ఇతరులను సంప్రదిస్తారు.", "A reused password is exposed, or a fake support message steals a sign-in code.", "మళ్లీ వాడిన పాస్‌వర్డ్ బయటపడటం లేదా నకిలీ సహాయక సందేశం లాగిన్ కోడ్ తీసుకోవడం.", "Unexpected login alerts; changed recovery details; messages you did not send.", "మీరు చేయని లాగిన్ హెచ్చరికలు; మారిన రికవరీ వివరాలు; మీరు పంపని సందేశాలు.", "Friends receive an urgent request for money from your account that you did not send.", "మీరు పంపకపోయినా మీ ఖాతా నుంచి డబ్బు అడిగే అత్యవసర సందేశం స్నేహితులకు రావడం.", "Use the platform's official recovery process, change reused passwords, and enable multi-factor authentication.", "ప్లాట్‌ఫారమ్ అధికారిక రికవరీ ప్రక్రియ వాడండి, మళ్లీ వాడిన పాస్‌వర్డ్ మార్చండి, బహుళ-దశ ధృవీకరణ ప్రారంభించండి.", "Recover the account through official support, warn contacts using another channel, and preserve alerts and messages.", "అధికారిక సహాయంతో ఖాతా తిరిగి పొందండి, మరో మార్గంలో పరిచయస్తులను హెచ్చరించి హెచ్చరికలు, సందేశాలు భద్రపరచండి."),
    ("cyberbullying", "Cyberbullying", "సైబర్ వేధింపులు", "Repeated harmful or humiliating behavior directed at a person through digital services.", "డిజిటల్ సేవల ద్వారా ఒక వ్యక్తిని పదేపదే బాధించే లేదా అవమానించే ప్రవర్తన.", "Insults, threats, unwanted sharing of images, or repeated targeting in chats and posts.", "చాట్‌లు, పోస్టుల్లో అవమానాలు, బెదిరింపులు, అనుమతి లేని చిత్రాల పంచకం లేదా పదేపదే లక్ష్యంగా చేయడం.", "Repeated unwanted contact; threats; doxxing; content shared without consent.", "అనవసరంగా పదేపదే సంప్రదించడం; బెదిరింపులు; వ్యక్తిగత వివరాలు బయటపెట్టడం; అనుమతి లేని కంటెంట్.", "A group repeatedly posts edited images of a student and tags them to cause distress.", "ఒక విద్యార్థిని బాధించడానికి గ్రూప్ ఎడిట్ చేసిన చిత్రాలను పదేపదే పోస్ట్ చేసి ట్యాగ్ చేయడం.", "Do not retaliate. Save URLs, dates, and screenshots; block and report the account on the platform.", "ప్రతీకారం చేయవద్దు. లింకులు, తేదీలు, స్క్రీన్‌షాట్‌లు భద్రపరచి ప్లాట్‌ఫారమ్‌లో బ్లాక్ చేసి నివేదించండి.", "Tell a trusted adult or support person. Use the official portal for serious threats or abuse; seek immediate local help if in danger.", "నమ్మకమైన పెద్దవారు లేదా సహాయక వ్యక్తికి చెప్పండి. తీవ్రమైన బెదిరింపులకు అధికారిక పోర్టల్ వాడండి; ప్రమాదంలో ఉంటే వెంటనే స్థానిక సహాయం పొందండి."),
    ("identity-theft", "Identity Theft", "గుర్తింపు దొంగతనం", "Personal information is used by someone else without permission, potentially to access services or impersonate you.", "వ్యక్తిగత సమాచారాన్ని అనుమతి లేకుండా ఇతరులు సేవలు పొందడానికి లేదా మీలా నటించడానికి వాడటం.", "Fake forms, data leaks, or impersonation messages collect identity details.", "నకిలీ ఫారాలు, డేటా లీకులు లేదా వేషధారణ సందేశాల ద్వారా గుర్తింపు వివరాలు సేకరించడం.", "Accounts or applications you did not create; unexpected verification messages; unfamiliar transactions.", "మీరు తెరవని ఖాతా లేదా కొనుగోలుకు సంబంధించిన నోటీసులు అందుతాయి; అనుకోని ధృవీకరణ సందేశాలు; తెలియని లావాదేవీలు.", "You receive notices for an account or purchase you never opened.", "మీరు తెరవని ఖాతా లేదా ఖరీదుకు సంబంధించిన తెలియజెప్పులు వస్తాయి.", "Share identity documents only through verified official channels and limit unnecessary copies.", "గుర్తింపు పత్రాలను ధృవీకరించిన అధికారిక మార్గాల్లోనే పంచుకొని అవసరం లేని కాపీలను తగ్గించండి.", "Contact the affected service or bank, secure accounts, and report suspected misuse through the official portal.", "సంబంధిత సేవ లేదా బ్యాంకును సంప్రదించి ఖాతాలు భద్రపరచండి; అనుమానిత దుర్వినియోగాన్ని అధికారిక పోర్టల్‌లో నివేదించండి."),
    ("sim-swap", "SIM Swap Fraud", "సిమ్ స్వాప్ మోసం", "A fraudster improperly takes control of a phone number, which may affect calls and messages.", "మోసగాడు ఫోన్ నంబర్‌పై అనధికార నియంత్రణ పొందడం వల్ల కాల్స్, సందేశాలు ప్రభావితం కావచ్చు.", "A criminal impersonates you to persuade a provider to issue a replacement SIM.", "మీలా నటించి కొత్త సిమ్ ఇవ్వమని సేవా సంస్థను ఒప్పించడం.", "Phone suddenly loses service; unexpected SIM change notice; account recovery messages stop arriving.", "ఫోన్‌లో అకస్మాత్తుగా నెట్‌వర్క్ పోవడం; సిమ్ మార్పు నోటీసు; రికవరీ సందేశాలు రాకపోవడం.", "Your phone loses network and your email reports a password reset you did not request.", "ఫోన్ నెట్‌వర్క్ కోల్పోయి, మీరు కోరని పాస్‌వర్డ్ రీసెట్ ఈమెయిల్ రావడం.", "Contact your mobile provider using an official channel immediately; secure email and financial accounts from another device.", "అధికారిక మార్గంలో మొబైల్ సేవా సంస్థను వెంటనే సంప్రదించండి; మరో పరికరం నుంచి ఈమెయిల్, ఆర్థిక ఖాతాలు భద్రపరచండి.", "Ask the provider to restore control, notify your bank, change exposed credentials, and report financial loss through 1930.", "నంబర్ నియంత్రణ తిరిగి పొందడానికి సేవా సంస్థను అడిగి, బ్యాంకుకు తెలియజేసి, బయటపడ్డ వివరాలు మార్చి, ఆర్థిక నష్టం 1930కు నివేదించండి."),
    ("qr-scam", "QR Code Scams", "క్యూఆర్ కోడ్ మోసాలు", "A QR code is used to direct you to a payment, login, or other destination you did not intend.", "మీరు ఉద్దేశించని చెల్లింపు, లాగిన్ లేదా ఇతర గమ్యానికి QR కోడ్ దారి మళ్లించవచ్చు.", "A scammer replaces a merchant's code or claims scanning a code will receive a refund.", "వ్యాపారి కోడ్‌ను మార్చడం లేదా కోడ్ స్కాన్ చేస్తే రిఫండ్ వస్తుందని చెప్పడం.", "The displayed payee is unfamiliar; scanning prompts a payment or asks for a PIN to receive funds.", "చూపిన చెల్లింపుదారు తెలియనివాడు; స్కాన్ తర్వాత చెల్లింపు లేదా డబ్బు పొందేందుకు పిన్ అడగడం.", "A supposed buyer sends a QR image and tells you to enter your UPI PIN to collect money.", "డబ్బు స్వీకరించడానికి UPI పిన్ ఇవ్వాలని చెప్పి కొనుగోలుదారు QR చిత్రం పంపడం.", "Check the destination and payee shown in the official app before approving. Do not enter a PIN to receive money.", "ఆమోదించే ముందు అధికారిక యాప్‌లో గమ్యం, చెల్లింపుదారుని పరిశీలించండి. డబ్బు పొందడానికి పిన్ ఇవ్వవద్దు.", "Contact your payment provider or bank immediately and call 1930 promptly if a payment was made by deception.", "చెల్లింపు సంస్థ లేదా బ్యాంకును వెంటనే సంప్రదించి, మోసంతో చెల్లింపు జరిగితే 1930కు వెంటనే కాల్ చేయండి."),
    ("remote-access", "Remote Access Application Scams", "రిమోట్ యాక్సెస్ యాప్ మోసాలు", "Someone persuades you to install an app or share a code that lets them view or control your device.", "యాప్ ఇన్‌స్టాల్ చేయమని లేదా కోడ్ పంచమని చెప్పి మీ పరికరాన్ని చూడటానికి లేదా నియంత్రించడానికి ప్రయత్నిస్తారు.", "A fake support agent says remote access is needed to issue a refund or fix an account.", "రిఫండ్ ఇవ్వడానికి లేదా ఖాతా సరిచేయడానికి రిమోట్ యాక్సెస్ అవసరమని నకిలీ సహాయకుడు చెప్పడం.", "Unsolicited request to install a screen-sharing app; instructions to open banking apps while sharing screen.", "స్క్రీన్ షేరింగ్ యాప్ ఇన్‌స్టాల్ చేయమని అనుకోని అభ్యర్థన; స్క్రీన్ పంచుతూ బ్యాంక్ యాప్ తెరవమని సూచించడం.", "A caller asks you to install a remote support app and read out its connection code.", "రిమోట్ సపోర్ట్ యాప్ ఇన్‌స్టాల్ చేసి కనెక్షన్ కోడ్ చెప్పమని కాలర్ అడగడం.", "Do not grant device access to an unsolicited caller. Contact the company through a known official channel.", "అనుకోని కాలర్‌కు పరికర యాక్సెస్ ఇవ్వవద్దు. తెలిసిన అధికారిక మార్గంలో సంస్థను సంప్రదించండి.", "Disconnect the session, uninstall the untrusted app, contact your bank from another device, and change exposed credentials.", "సెషన్ నిలిపి నమ్మని యాప్ తొలగించండి, మరో పరికరం నుంచి బ్యాంకును సంప్రదించి బయటపడ్డ వివరాలు మార్చండి."),
    ("investment-scam", "Investment and Trading Scams", "పెట్టుబడి మరియు ట్రేడింగ్ మోసాలు", "A false investment offer uses misleading claims to persuade people to send money or reveal account access.", "తప్పుదారి పట్టించే లాభాల హామీలతో డబ్బు పంపించడానికి లేదా ఖాతా యాక్సెస్ ఇవ్వడానికి ఒప్పిస్తారు.", "Fake trading groups, copied adviser profiles, or pressure to add funds to withdraw supposed profits.", "నకిలీ ట్రేడింగ్ గ్రూపులు, నకిలీ సలహాదారు ప్రొఫైళ్లు లేదా లాభాలు తీసుకోవడానికి మరింత డబ్బు జమ ఒత్తిడి.", "Guaranteed returns; urgency; unclear registration; withdrawal blocked pending extra fee.", "హామీ లాభాలు; తొందర; స్పష్టతలేని నమోదు; అదనపు ఫీజు వరకు విత్‌డ్రా నిలిపివేత.", "A group displays apparent profits but demands a tax payment before allowing withdrawal.", "లాభాలు కనిపిస్తున్నాయని చూపి, విత్‌డ్రా ముందు పన్ను చెల్లించమని గ్రూప్ అడగడం.", "Verify the firm and adviser independently through official regulator resources. Never rely only on screenshots or group messages.", "సంస్థ, సలహాదారుని అధికారిక నియంత్రణ సంస్థ వనరుల ద్వారా స్వతంత్రంగా ధృవీకరించండి. స్క్రీన్‌షాట్‌లు లేదా గ్రూప్ సందేశాలపై మాత్రమే ఆధారపడవద్దు.", "Stop sending money, keep transaction records, contact your bank, and call 1930 promptly for financial cyber fraud.", "డబ్బు పంపడం ఆపి లావాదేవీ రికార్డులు ఉంచండి, బ్యాంకును సంప్రదించి ఆర్థిక సైబర్ మోసం అయితే 1930కు వెంటనే కాల్ చేయండి."),
    ("malware-ransomware", "Malware and Ransomware", "మాల్వేర్ మరియు ర్యాన్సమ్‌వేర్", "Malware is software that can harm a device or misuse data; ransomware may lock or encrypt files and demand payment.", "పరికరానికి హాని చేసే లేదా డేటాను దుర్వినియోగం చేసే సాఫ్ట్‌వేర్ మాల్వేర్; ర్యాన్సమ్‌వేర్ ఫైళ్లను లాక్ చేసి డబ్బు అడగవచ్చు.", "Malicious attachments, untrusted downloads, or software from unofficial sources.", "హానికరమైన జోడింపులు, నమ్మని డౌన్‌లోడ్‌లు లేదా అనధికారిక మూలాల సాఫ్ట్‌వేర్.", "Unexpected encryption note; security tools disabled; unusual pop-ups or apps; files suddenly inaccessible.", "అనుకోని ఎన్‌క్రిప్షన్ నోట్; భద్రతా సాధనాలు ఆగిపోవడం; అసాధారణ పాప్‌అప్‌లు లేదా యాప్‌లు; ఫైళ్లు తెరవలేకపోవడం.", "A document from an unknown sender asks you to enable content and then files become unavailable.", "తెలియని వ్యక్తి పంపిన పత్రంలో కంటెంట్ ప్రారంభించమని అడగడం, తర్వాత ఫైళ్లు అందుబాటులో లేకపోవడం.", "Keep software updated, use reputable security tools, keep backups disconnected when not in use, and avoid unexpected attachments.", "సాఫ్ట్‌వేర్ నవీకరించండి, విశ్వసనీయ భద్రతా సాధనాలు వాడండి, వాడనప్పుడు బ్యాకప్‌లను వేరుగా ఉంచండి, అనుకోని జోడింపులు తెరవవద్దు.", "Disconnect the affected device from networks, do not delete evidence, and seek trusted technical response support. Avoid paying without expert advice.", "ప్రభావిత పరికరాన్ని నెట్‌వర్క్ నుంచి వేరు చేసి ఆధారాలు తొలగించవద్దు; నమ్మకమైన సాంకేతిక సహాయం పొందండి. నిపుణుల సలహా లేకుండా చెల్లించవద్దు."),
    ("shopping-fraud", "Online Shopping Fraud", "ఆన్‌లైన్ కొనుగోలు మోసం", "A fake seller or storefront takes payment or data but does not provide the promised goods or service.", "నకిలీ విక్రేత లేదా దుకాణం డబ్బు లేదా వివరాలు తీసుకుని వాగ్దానం చేసిన వస్తువు/సేవ ఇవ్వకపోవచ్చు.", "Copied store pages, unusually low prices, off-platform payment requests, or fake delivery updates.", "కాపీ చేసిన దుకాణ పేజీలు, అసాధారణంగా తక్కువ ధరలు, ప్లాట్‌ఫారమ్ బయట చెల్లింపు లేదా నకిలీ డెలివరీ సమాచారం.", "Seller avoids the platform; no verifiable address; pressure to pay by an irreversible method.", "విక్రేత ప్లాట్‌ఫారమ్‌ను తప్పించుకోవడం; ధృవీకరించగల చిరునామా లేకపోవడం; తిరిగి పొందలేని మార్గంలో చెల్లింపు ఒత్తిడి.", "A seller offers a discount if you cancel the marketplace order and pay a personal account directly.", "మార్కెట్‌ప్లేస్ ఆర్డర్ రద్దు చేసి వ్యక్తిగత ఖాతాకు చెల్లిస్తే తగ్గింపు ఇస్తామని విక్రేత చెప్పడం.", "Use the platform's payment and dispute process; verify the seller and return terms before paying.", "ప్లాట్‌ఫారమ్ చెల్లింపు, వివాద పరిష్కార విధానం వాడండి; చెల్లింపుకు ముందు విక్రేత, రిటర్న్ నిబంధనలు ధృవీకరించండి.", "Contact the platform and payment provider, preserve order records, and call 1930 if the loss involved financial cyber fraud.", "ప్లాట్‌ఫారమ్, చెల్లింపు సంస్థను సంప్రదించి ఆర్డర్ రికార్డులు భద్రపరచండి; ఆర్థిక సైబర్ మోసం అయితే 1930కు కాల్ చేయండి."),
    ("impersonation", "Impersonation Scams", "వేషధారణ మోసాలు", "A person pretends to be someone you trust, such as a relative, official, employer, or service provider.", "బంధువు, అధికారి, ఉద్యోగదాత లేదా సేవా సంస్థగా ఒకరు నటిస్తారు.", "A compromised or copied profile sends an urgent request for money or confidential information.", "హ్యాక్ చేసిన లేదా కాపీ చేసిన ప్రొఫైల్ అత్యవసరంగా డబ్బు లేదా రహస్య సమాచారం అడగడం.", "Unexpected emergency; request to keep it secret; changed number or account; payment to a new recipient.", "అనుకోని అత్యవసర పరిస్థితి; రహస్యంగా ఉంచమని అడగడం; మారిన నంబర్ లేదా ఖాతా; కొత్త వ్యక్తికి చెల్లింపు.", "A message using a friend's photo says they lost their phone and need money immediately.", "స్నేహితుడి ఫోటోతో ఉన్న సందేశం ఫోన్ పోయిందని వెంటనే డబ్బు కావాలని చెప్పడం.", "Verify through a separate known contact route, such as calling the saved number. Do not rely on the same chat.", "సేవ్ చేసిన నంబర్‌కు కాల్ చేయడం వంటి వేరే తెలిసిన మార్గంలో ధృవీకరించండి. అదే చాట్‌పై ఆధారపడవద్దు.", "Contact your bank if you paid, warn the impersonated person, preserve messages, and call 1930 for financial cyber fraud.", "చెల్లించి ఉంటే బ్యాంకును సంప్రదించి, ఎవరి పేరుతో నటించారో వారికి తెలియజేసి, సందేశాలు భద్రపరచి ఆర్థిక మోసం అయితే 1930కు కాల్ చేయండి."),
    ("sextortion-harassment", "Sextortion and Online Harassment", "ఆన్‌లైన్ బెదిరింపులు మరియు వ్యక్తిగత కంటెంట్‌తో బ్లాక్‌మెయిల్", "Someone threatens to share private content or harass a person unless they comply with demands.", "వ్యక్తిగత కంటెంట్ బయటపెడతామని లేదా వేధిస్తామని బెదిరించి డిమాండ్లు నెరవేర్చమంటారు.", "It may begin through a fake profile, a compromised account, or pressure to move a conversation to a private channel.", "నకిలీ ప్రొఫైల్, ఖాతా దుర్వినియోగం లేదా సంభాషణను వ్యక్తిగత మార్గానికి మార్చమనే ఒత్తిడితో ఇది ప్రారంభం కావచ్చు.", "Threats, repeated demands for money, or pressure to send more private material.", "బెదిరింపులు; మళ్లీ మళ్లీ డబ్బు అడగడం; మరింత వ్యక్తిగత కంటెంట్ పంపమని ఒత్తిడి.", "A person threatens to publish private images unless a payment is made immediately.", "వెంటనే డబ్బు చెల్లించకపోతే వ్యక్తిగత చిత్రాలు ప్రచురిస్తామని బెదిరించడం.", "Do not send more content or money. Preserve account names, URLs, and messages; report the account to the platform.", "మరింత కంటెంట్ లేదా డబ్బు పంపవద్దు. ఖాతా పేర్లు, లింకులు, సందేశాలు భద్రపరచి ప్లాట్‌ఫారమ్‌కు నివేదించండి.", "Seek support from a trusted person and report serious threats through the official portal. If a child is involved, involve a trusted adult promptly.", "నమ్మకమైన వ్యక్తి సహాయం తీసుకొని తీవ్రమైన బెదిరింపులను అధికారిక పోర్టల్‌లో నివేదించండి. బాలుడు/బాలికకు సంబంధించినదైతే వెంటనే నమ్మకమైన పెద్దవారిని కలపండి."),
    ("website-link-scams", "Website and Link-Based Scams", "వెబ్‌సైట్ మరియు లింక్ మోసాలు", "A deceptive website imitates a trusted service or uses misleading content to collect money or information.", "నమ్మకమైన సేవలా కనిపించే మోసపూరిత వెబ్‌సైట్ డబ్బు లేదా సమాచారాన్ని సేకరించవచ్చు.", "Lookalike domains, misspelled addresses, fake login pages, or unsolicited QR/link redirects.", "పోలిక ఉన్న డొమైన్‌లు, తప్పు స్పెల్లింగ్ చిరునామాలు, నకిలీ లాగిన్ పేజీలు లేదా అనుకోని QR/లింక్ మళ్లింపులు.", "The domain differs from the official one; the page asks for secret codes or unrelated permissions.", "డొమైన్ అధికారిక దానితో భిన్నంగా ఉండటం; రహస్య కోడ్‌లు లేదా సంబంధంలేని అనుమతులు అడగడం.", "A search advert leads to a page that looks like a bank but has a slightly changed address.", "శోధన ప్రకటన బ్యాంక్‌లా కనిపించే కానీ చిరునామా కొద్దిగా మారిన పేజీకి తీసుకెళ్లడం.", "Do not sign in through an unsolicited link. Navigate from the official app or a saved bookmark; never use appearance alone to verify.", "అనుకోని లింక్ ద్వారా లాగిన్ అవ్వవద్దు. అధికారిక యాప్ లేదా సేవ్ చేసిన బుక్‌మార్క్ వాడండి; రూపాన్ని చూసి మాత్రమే ధృవీకరించవద్దు.", "If credentials were entered, change them from the official site and notify the service. Call 1930 if money was lost.", "లాగిన్ వివరాలు ఇచ్చినట్లయితే అధికారిక సైట్‌లో మార్చి సేవా సంస్థకు తెలియజేయండి. డబ్బు పోయితే 1930కు కాల్ చేయండి."),
]


def _build_items():
    items = []
    for row in _ITEMS:
        (slug, title_en, title_te, definition_en, definition_te, methods_en, methods_te,
         signs_en, signs_te, example_en, example_te, prevent_en, prevent_te, response_en, response_te) = row
        items.append({
            "id": slug,
            "title": {"en": title_en, "te": title_te},
            "definition": {"en": definition_en, "te": definition_te},
            "how_it_happens": {"en": methods_en, "te": methods_te},
            "common_methods": {"en": methods_en, "te": methods_te},
            "warning_signs": {"en": signs_en.split("; "), "te": signs_te.split("; ")},
            "example": {"en": example_en, "te": example_te},
            "how_to_identify": {"en": signs_en, "te": signs_te},
            "prevention": {"en": prevent_en, "te": prevent_te},
            "if_affected": {"en": response_en, "te": response_te},
            "reporting_resources": REPORTING_RESOURCES,
            "content_note": "Illustrative guidance only. It does not determine whether a specific event is a crime.",
        })
    return items


ITEMS = _build_items()


@router.get("/crimes")
def list_cybercrime_guides(
    q: str | None = Query(None, max_length=100),
    language: str = Query("en", pattern="^(en|te)$"),
):
    items = ITEMS
    if q:
        needle = q.casefold().strip()
        items = [item for item in items if any(
            needle in item[field][language].casefold()
            for field in ("title", "definition", "how_it_happens", "example")
        )]
    return {
        "language": language,
        "count": len(items),
        "items": items,
        "sources": [
            {"name": resource["name"], "url": resource["url"], "publisher": resource["source"]}
            for resource in REPORTING_RESOURCES
        ],
    }
